def search_cities(state="Ohio"):
    path = os.path.join(DATA_DIR, "background/citySet_with_states.txt")
    cities = []
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        for line in f:
            parts = line.strip().split("\t")
            if len(parts) >= 2 and parts[1].strip().lower() == state.lower():
                cities.append(parts[0].strip())
    return cities

